def solve(num: int) -> str:
    if num == 0:
        return "Zero"
    return "Even" if num % 2 == 0 else "Odd"

def solve(n: int) -> int:
    sign = -1 if n < 0 else 1
    s = str(abs(n))[::-1]
    return sign * int(s)

def solve(s: str) -> tuple:
    vowels = set("aeiou")
    v_cnt = sum(1 for c in s.lower() if c in vowels)
    c_cnt = sum(1 for c in s.lower() if c.isalpha() and c not in vowels)
    return (v_cnt, c_cnt)

def solve(n: int) -> int:
    ans = 1
    for i in range(1, n + 1):
        ans *= i
    return ans

def solve(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def solve(n: int) -> int:
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def solve(n: int) -> bool:
    if n <= 1: return False
    if n <= 3: return True
    if n % 2 == 0 or n % 3 == 0: return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve(n: int) -> int:
    cnt = 0
    while n:
        n &= (n - 1)
        cnt += 1
    return cnt

def solve(a: int, b: int) -> tuple:
    a, b = b, a
    return (a, b)
